const ws=document.createElement('main');ws.id='trozalImageCodeVideoWorkspace';ws.innerHTML='<div class="shell"><section class="panel"><div class="row"><h2 style="flex:1">IMAGE TO CODE VIDEO</h2><button id="itcvBack">← Kembali</button></div><p>Mode mandiri di luar Mode Profesional. Ubah gambar raster menjadi video HTML mandiri dengan CSS @keyframes yang ramah importer. JavaScript output kompatibel dengan JavaScript Studio: draw(ctx, t, w, h, anim).</p><label>Gambar sumber (maksimal 3)</label><input id="itcvFiles" type="file" accept="image/png,image/jpeg,image/webp" multiple><div class="thumbs" id="itcvThumbs"></div><label>Gaya animasi</label><select id="itcvStyle"><option value="cinematic">Cinematic camera push, pan, parallax, light</option><option value="product">Premium product commercial</option><option value="dynamic">Dynamic camera and energy particles</option><option value="dream">Dreamlike floating camera and glow</option><option value="editorial">Clean editorial camera slide</option></select><label>Instruksi gerakan tambahan</label><textarea id="itcvPrompt" rows="3" placeholder="Arah kamera, suasana, gerakan objek..."></textarea><div class="row"><div><label>Durasi (detik)</label><input id="itcvDuration" type="number" min="2" max="60" value="8"></div><div><label>FPS</label><select id="itcvFps"><option>24</option><option selected>30</option><option>60</option></select></div></div><div class="row"><div><label>Rasio video</label><select id="itcvRatio"><option value="16:9">16:9 Landscape</option><option value="9:16">9:16 Portrait</option><option value="1:1">1:1 Square</option><option value="4:5">4:5 Social</option></select></div><div><label>Gambar</label><select id="itcvFit"><option value="contain">Utuh / Tidak terpotong</option><option value="cover">Isi kanvas / Crop</option></select></div></div><label class="rig-auto"><input id="itcvAutoRig" type="checkbox" checked> Auto Universal Rig: pisahkan objek/komponen dengan SAM 2.1 Tiny di GPU browser (model diunduh sekali dan disimpan di cache)</label><div class="actions"><button class="primary" id="itcvGenerate">✦ ANALISIS & GENERATE</button><button id="itcvBuildRig">◈ AI SEGMENTASI KOMPONEN & BUILD UNIVERSAL RIG</button><button id="itcvTemplate">Animasi dasar</button></div><div id="itcvStatus" class="status">Pilih gambar raster. Preview memakai rasio terpilih dan animasi nyata.</div></section><section class="panel"><div class="preview"><div class="row"><strong style="flex:1">LIVE VIDEO PREVIEW</strong><span id="itcvMeta">16:9 · 30 FPS</span><button id="itcvPlay">Ⅱ Pause</button></div><iframe id="itcvPreview" title="Image to video preview" sandbox="allow-scripts allow-same-origin"></iframe></div><section class="scene-director" id="itcvSceneDirector"><h3>✦ AI SCENE MOTION DIRECTOR</h3><div class="scene-desc" id="itcvSceneDescription">Belum ada analisis scene. Klik ANALISIS & GENERATE untuk membuat scene motion.</div><div class="scene-layers" id="itcvSceneLayers"></div><div class="rig-panel" id="itcvRigPanel"><h4>◈ UNIVERSAL OBJECT & CHARACTER RIG · SAM 2.1 TINY / WEBGPU</h4><div id="itcvRigStatus" class="rig-status">Upload satu gambar, jalankan AI Vision untuk mendapatkan nama/kotak komponen, atau klik objek pada gambar di bawah untuk memilih titik manual. SAM memisahkan mask piksel secara lokal di GPU browser.</div><canvas id="itcvRigSource" class="rig-source" width="640" height="360" aria-label="Klik objek untuk menambahkan komponen manual"></canvas><div class="rig-status">Klik gambar untuk menambah mask manual. Nama, gerakan, dan parent setiap bagian dapat diedit sebelum menyalin HTML/JavaScript.</div><div class="scene-layers" id="itcvRigParts"></div></div><div class="scene-controls"><div><label>Camera motion</label><select id="itcvCameraMove"><option value="push-in">Cinematic push-in</option><option value="pan">Pan horizontal</option><option value="orbit">Orbit / drift</option><option value="static">Static camera</option></select></div><div><label>Motion intensity</label><input id="itcvMotionIntensity" type="range" min="0" max="2" step="0.1" value="1"></div></div><div class="scene-controls"><div><label>Atmosphere</label><select id="itcvAtmosphere"><option value="cinematic">Cinematic particles</option><option value="clean">Clean / minimal</option><option value="dream">Dreamlike glow</option></select></div><div><label>Layer count</label><div id="itcvLayerCount" class="status">0 active layers</div></div></div><div class="scene-controls"><div><label>Camera shake</label><input id="itcvCameraShake" type="range" min="0" max="2" step="0.1" value="0.4"></div><div><label>Color grade</label><select id="itcvColorGrade"><option value="none">Original</option><option value="warm">Warm cinematic</option><option value="cool">Cool blue</option><option value="mono">Monochrome</option></select></div></div><div class="scene-controls"><div><label>Background</label><select id="itcvBackground"><option value="#050a10">Deep black</option><option value="#101820">Graphite</option><option value="#f2f4f7">Soft white</option><option value="#102b35">Deep teal</option></select></div><div><label>Finishing</label><label style="display:flex;align-items:center;gap:7px"><input id="itcvVignette" type="checkbox" checked style="width:auto"> Vignette</label><label style="display:flex;align-items:center;gap:7px"><input id="itcvLoop" type="checkbox" checked style="width:auto"> Seamless loop</label></div></div><div class="scene-controls"><div><label>Universal Rig · Kecepatan global</label><input id="itcvRigSpeed" type="range" min="0.25" max="3" step="0.05" value="1"></div><div><label>Universal Rig · Kekuatan gerak</label><input id="itcvRigAmplitude" type="range" min="0" max="2.5" step="0.05" value="1"></div></div><div class="scene-controls"><div><label>Depth Parallax</label><label style="display:flex;align-items:center;gap:7px"><input id="itcvRigParallax" type="checkbox" checked style="width:auto"> Gerak kedalaman antar komponen</label></div><div><label>Soft Contact Shadow</label><label style="display:flex;align-items:center;gap:7px"><input id="itcvRigShadow" type="checkbox" checked style="width:auto"> Bayangan layer lembut</label></div></div><div class="scene-controls"><div><label>Stagger Motion</label><label style="display:flex;align-items:center;gap:7px"><input id="itcvRigStagger" type="checkbox" checked style="width:auto"> Perbedaan fase tiap komponen</label></div><div><label>Catatan</label><div class="status">Pengaturan ini ikut tertanam pada HTML dan JavaScript ekspor.</div></div></div><div class="scene-controls"><div><label>Camera Zoom Range</label><input id="itcvCameraZoom" type="range" min="0.85" max="1.35" step="0.01" value="1.05"></div><div><label>Film Grain</label><input id="itcvFilmGrain" type="range" min="0" max="0.25" step="0.01" value="0.06"></div></div><div class="scene-controls"><div><label>Focus X · Horizontal</label><input id="itcvFocusX" type="range" min="0" max="1" step="0.01" value="0.5"></div><div><label>Focus Y · Vertical</label><input id="itcvFocusY" type="range" min="0" max="1" step="0.01" value="0.5"></div></div><div class="scene-controls"><div><label>Lens Softness</label><input id="itcvLensSoftness" type="range" min="0" max="3" step="0.1" value="0"></div><div><label>Catatan Kamera</label><div class="status">Zoom, titik fokus, grain, dan softness ikut tersimpan dalam HTML/JavaScript ekspor.</div></div></div><div class="actions"><button id="itcvRebuildScene">↻ Terapkan pengaturan scene</button></div></section><div class="out"><label>HTML VIDEO OUTPUT · CSS @KEYFRAMES (IMPORTER-SAFE)</label><textarea id="itcvHtml" spellcheck="false"></textarea><div class="actions"><button class="primary" id="itcvCopyHtml">Copy HTML</button><button id="itcvDownloadHtml">Download HTML</button></div></div><div class="out"><label>JAVASCRIPT OUTPUT · JAVASCRIPT STUDIO draw(ctx,t,w,h,anim)</label><textarea id="itcvJs" spellcheck="false"></textarea><div class="actions"><button class="primary" id="itcvCopyJs">Copy JavaScript</button><button id="itcvDownloadJs">Download JavaScript</button></div></div></section></div>';document.body.append(ws);
