  name.addEventListener('change',()=>{part.name=name.value.slice(0,72);if(currentRig)output(currentScene||{description:'Universal Rig',layers:[]});});
  const motion=document.createElement('select');motion.title='Jenis gerakan';
  ['swing','hinge','wheel','rotate','bob','float','pulse','static'].forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;motion.append(o);});
  motion.value=part.motion||'swing';motion.addEventListener('change',()=>{part.motion=motion.value;if(currentRig)output(currentScene||{description:'Universal Rig',layers:[]});});
  editor.append(check,name,motion);row.append(editor);
  const addRigSlider=(key,label,min,max,step,value,apply)=>{
   const wrap=document.createElement('label');wrap.style.cssText='display:block;margin:7px 0 3px;font-size:11px;color:#b9d9e7';
   const title=document.createElement('span');title.textContent=label+' · '+Number(value).toFixed(key==='pivotX'||key==='pivotY'?0:2);
   const slider=document.createElement('input');slider.type='range';slider.min=String(min);slider.max=String(max);slider.step=String(step);slider.value=String(value);slider.dataset.rigControl=key;slider.style.width='100%';
   slider.addEventListener('input',()=>{const v=Number(slider.value);title.textContent=label+' · '+v.toFixed(key==='pivotX'||key==='pivotY'?0:2);apply(v);if(currentRig)output(currentScene||{description:'Universal Rig',layers:[]});});
   wrap.append(title,slider);row.append(wrap);
  };
  addRigSlider('speedMultiplier','Kecepatan bagian',.1,3,.05,part.speedMultiplier==null?1:part.speedMultiplier,v=>part.speedMultiplier=v);
  addRigSlider('amplitudeMultiplier','Kekuatan bagian',0,2.5,.05,part.amplitudeMultiplier==null?1:part.amplitudeMultiplier,v=>part.amplitudeMultiplier=v);
  addRigSlider('opacity','Opacity layer',0,1,.05,part.opacity==null?1:part.opacity,v=>part.opacity=v);
  const rigWidth=Number(rig&&rig.width)||1280,rigHeight=Number(rig&&rig.height)||720;
  addRigSlider('pivotX','Pivot X',0,rigWidth,1,Number(part.pivotX)||0,v=>part.pivotX=v);
  addRigSlider('pivotY','Pivot Y',0,rigHeight,1,Number(part.pivotY)||0,v=>part.pivotY=v);
  if(rig&&part.parent!==undefined){
   const parent=document.createElement('select');parent.title='Parent / hierarki';
   const root=document.createElement('option');root.value='';root.textContent='Root / tanpa parent';parent.append(root);
   rig.parts.filter(p=>p.id!==part.id).forEach(p=>{const o=document.createElement('option');o.value=p.id;o.textContent=p.name;parent.append(o);});
   parent.value=part.parent||'';parent.addEventListener('change',()=>{part.parent=parent.value||null;if(currentRig)output(currentScene||{description:'Universal Rig',layers:[]});});
   const parentLabel=document.createElement('label');parentLabel.style.margin='5px 0 0';parentLabel.textContent='Parent';parentLabel.append(parent);row.append(parentLabel);
  }
