function renderSceneDirector(scene){currentScene=scene&&typeof scene==='object'?scene:{description:String(scene||'Motion template'),layers:[]};$('itcvSceneDescription').textContent=currentScene.description||'AI scene plan siap.';const host=$('itcvSceneLayers');host.replaceChildren();(currentScene.layers||[]).forEach((layer,i)=>{const label=document.createElement('label');label.className='scene-layer';const check=document.createElement('input');check.type='checkbox';check.checked=layer.enabled!==false;check.addEventListener('change',()=>{layer.enabled=check.checked;output(currentScene);});const name=document.createElement('span');name.textContent=(layer.name||('Layer '+(i+1)))+' · '+(layer.kind||'glow');label.append(check,name);host.append(label);});$('itcvLayerCount').textContent=(currentScene.layers||[]).filter(x=>x.enabled!==false).length+' / '+(currentScene.layers||[]).length+' active layers';renderRigDirector(currentRig);$('itcvSceneDirector').style.display='block';}
